module TopModule (
    input  clk,
    input  reset,
    input  s,
    input  w,
    output z
);

typedef enum logic [1:0] {A = 2'd0, B = 2'd1, C = 2'd2, D = 2'd3, E = 2'd4} state_t;

state_t current_state, next_state;
logic [2:0] count;
logic [2:0] w_values;

always_ff @(posedge clk or posedge reset) begin
    if (reset) begin
        current_state <= A;
        count <= 3'd0;
        w_values <= 3'd0;
    end else begin
        current_state <= next_state;
        if (current_state == E) begin
            count <= 3'd0;
            w_values <= w_values << 1;
            w_values[0] <= w;
        end else if (current_state == B) begin
            count <= count + 1;
            w_values <= w_values << 1;
            w_values[0] <= w;
        end
    end
end

always_comb begin
    next_state = current_state;
    z = 1'b0;

    case (current_state)
        A: begin
            if (s) begin
                next_state = B;
            end else begin
                next_state = A;
            end
        end

        B: begin
            next_state = B;
            if (count < 3) begin
                // Continue counting
            end else begin
                // Check if exactly two of the last three w values were 1
                if ((w_values[2] == 1) + (w_values[1] == 1) + (w_values[0] == 1) == 2) begin
                    z = 1'b1;
                end
                next_state = C;
            end
        end

        C: begin
            next_state = D;
        end

        D: begin
            next_state = E;
        end

        E: begin
            next_state = B;
        end
    endcase
end

endmodule

module TopModule (
    input  clk,
    input  load,
    input  [255:0] data,
    output reg [255:0] q
);

    // Internal registers for next state
    reg [255:0] next_q;

    // Compute next state based on current state q
    always @(posedge clk) begin
        if (load) begin
            q <= data;
        end else begin
            q <= next_q;
        end
    end

    // Compute next state
    always @(*) begin
        next_q = 256'b0;
        integer i, j, x, y, count;
        reg [3:0] neighbors;

        for (i = 0; i < 16; i = i + 1) begin
            for (j = 0; j < 16; j = j + 1) begin
                count = 0;
                // Check all 8 neighbors
                for (x = -1; x <= 1; x = x + 1) begin
                    for (y = -1; y <= 1; y = y + 1) begin
                        if (x == 0 && y == 0) continue;
                        // Toroidal wrap around
                        integer row = (i + x + 16) % 16;
                        integer col = (j + y + 16) % 16;
                        if (q[row * 16 + col]) count = count + 1;
                    end
                end

                // Apply Conway's Game of Life rules
                if (count == 0 || count == 1) begin
                    neighbors = 4'b0000;
                end else if (count == 2) begin
                    neighbors = 4'b0001;
                end else if (count == 3) begin
                    neighbors = 4'b0010;
                end else begin
                    neighbors = 4'b0100;
                end

                // Determine next state
                if (neighbors == 4'b0000 || neighbors == 4'b0001) begin
                    next_q[i * 16 + j] = 1'b0;
                end else if (neighbors == 4'b0010) begin
                    next_q[i * 16 + j] = q[i * 16 + j];
                end else begin
                    next_q[i * 16 + j] = 1'b1;
                end
            end
        end
    end

endmodule

