        STATE_HIGH,    // Between s[2] and s[1]
        STATE_ABOVE    // Above s[2]
    } state_t;

    state_t current_state, next_state;

    // Previous sensor state
    reg [2:0] prev_s;

    // State transition logic
    always @(posedge clk or posedge reset) begin
        if (reset) begin
            current_state <= STATE_LOW;
            prev_s <= 3'b000; // All sensors not asserted (simulate low level)
            fr2 <= 1'b1;
            fr1 <= 1'b1;
            fr0 <= 1'b1;
            dfr <= 1'b0;
        end else begin
            current_state <= next_state;
            prev_s <= s;
        end
    end

    // Next state logic
    always @(*) begin
        next_state = current_state;

        case (s)
            3'b111: next_state = STATE_ABOVE; // Above s[2]
            3'b110: next_state = STATE_HIGH;  // Between s[2] and s[1]
            3'b100: next_state = STATE_MIDDLE; // Between s[1] and s[0]
            3'b000: next_state = STATE_LOW;   // Below s[0]
            default: next_state = current_state;
        endcase
    end

    // Output logic based on current state and previous sensor state
    always @(posedge clk) begin
        case (current_state)
            STATE_ABOVE: begin
                fr2 <= 1'b0;
                fr1 <= 1'b0;
                fr0 <= 1'b0;
                dfr <= 1'b0;
            end
            STATE_HIGH: begin
                fr2 <= 1'b0;
                fr1 <= 1'b0;
                fr0 <= 1'b0;
                dfr <= (prev_s < s) ? 1'b1 : 1'b0;
            end
            STATE_MIDDLE: begin
                fr2 <= 1'b0;
                fr1 <= 1'b1;
                fr0 <= 1'b1;
                dfr <= (prev_s < s) ? 1'b1 : 1'b0;
            end
            STATE_LOW: begin
                fr2 <= 1'b1;
                fr1 <= 1'b1;
                fr0 <= 1'b1;
                dfr <= 1'b0;
            end
        endcase
    end

endmodule

module TopModule (
    input  clk,
    input  areset,
    input  bump_left,
    input  bump_right,
    input  ground,
    input  dig,
    output reg walk_left,
    output reg walk_right,
    output reg aaah,
    output reg digging
);

typedef enum reg [2:0] {
    IDLE,
    WALK_LEFT,
    WALK_RIGHT,
    FALLING,
    DIGGING
} state_t;

state_t current_state, next_state;
reg [1:0] direction; // 0: left, 1: right
reg falling;
reg was_walking_left;
reg was_walking_right;
reg was_digging;

always @(posedge clk or posedge areset) begin
    if (areset) begin
        current_state <= IDLE;
        direction <= 0;
        falling <= 1'b0;
        was_walking_left <= 1'b0;
        was_walking_right <= 1'b0;
        was_digging <= 1'b0;
        walk_left <= 1'b0;
        walk_right <= 1'b0;
        aaah <= 1'b0;
        digging <= 1'b0;
    end else begin
        current_state <= next_state;
        falling <= 1'b0;
        was_walking_left <= walk_left;
        was_walking_right <= walk_right;
        was_digging <= digging;
        walk_left <= 1'b0;
        walk_right <= 1'b0;
        aaah <= 1'b0;
        digging <= 1'b0;

        if (current_state == IDLE) begin
            direction <= 0;
            next_state <= WALK_LEFT;
        end else if (current_state == WALK_LEFT) begin
            if (ground) begin
                if (dig) begin
                    next_state <= DIGGING;
                end else if (bump_right) begin
                    next_state <= WALK_RIGHT;
                end else if (!ground) begin
                    next_state <= FALLING;
                end else begin
                    next_state <= WALK_LEFT;
                end
            end else begin
                next_state <= FALLING;
            end
        end else if (current_state == WALK_RIGHT) begin
            if (ground) begin
                if (dig) begin
                    next_state <= DIGGING;
                end else if (bump_left) begin
                    next_state <= WALK_LEFT;
                end else if (!ground) begin
                    next_state <= FALLING;
                end else begin
                    next_state <= WALK_RIGHT;
                end
            end else begin
                next_state <= FALLING;
            end
        end else if (current_state == FALLING) begin
            if (ground) begin
                if (was_walking_left) begin
                    next_state <= WALK_LEFT;
                end else if (was_walking_right) begin
                    next_state <= WALK_RIGHT;
                end else begin
                    next_state <= IDLE;
                end
            end else begin
                next_state <= FALLING;
            end
        end else if (current_state == DIGGING) begin
            if (ground) begin
                if (dig) begin
                    next_state <= DIGGING;
                end else if (!ground) begin
                    next_state <= FALLING;
                end else begin
                    next_state <= WALK_LEFT;
                end
            end else begin
                next_state <= FALLING;
            end
        end
    end
end

always @(posedge clk or posedge areset) begin
    if (areset) begin
        walk_left <= 1'b0;
        walk_right <= 1'b0;
        aaah <= 1'b0;
        digging <= 1'b0;
    end else begin
        if (current_state == WALK_LEFT) begin
            walk_left <= 1'b1;
        end else if (current_state == WALK_RIGHT) begin
            walk_right <= 1'b1;
        end else if (current_state == FALLING) begin
            aaah <= 1'b1;
        end else if (current_state == DIGGING) begin
            digging <= 1'b1;
        end
    end
end

endmodule

